from comfy_api.latest import ComfyExtension

from .api_nodes import (
    NODE_CLASS_MAPPINGS,
    NODE_DISPLAY_NAME_MAPPINGS,
    SimpleAspectRatio,
)


class SimpleAspectRatioExtension(ComfyExtension):
    async def get_node_list(self):
        return [SimpleAspectRatio]


async def comfy_entrypoint():
    return SimpleAspectRatioExtension()


__all__ = [
    "NODE_CLASS_MAPPINGS",
    "NODE_DISPLAY_NAME_MAPPINGS",
    "comfy_entrypoint",
]

"""Public SDK registration for the unchanged upstream aspect-ratio calculation."""

from comfy_api.latest import io

from .aspect_ratio_node import SimpleAspectRatio as _OriginalSimpleAspectRatio


class SimpleAspectRatio(io.ComfyNode):
    SDK_REFS = False
    SDK_PERMISSIONS = ()

    @classmethod
    def define_schema(cls):
        required = _OriginalSimpleAspectRatio.INPUT_TYPES()["required"]
        return io.Schema(
            node_id="SimpleAspectRatio",
            display_name="Simple Aspect Ratio",
            category=_OriginalSimpleAspectRatio.CATEGORY,
            inputs=[
                io.Combo.Input("aspectRatio", options=required["aspectRatio"][0]),
                io.Combo.Input("orientation", options=required["orientation"][0]),
            ],
            outputs=[io.Int.Output("width"), io.Int.Output("height")],
        )

    @classmethod
    def execute(cls, aspectRatio, orientation):
        return io.NodeOutput(
            *_OriginalSimpleAspectRatio().get_size(aspectRatio, orientation)
        )


NODE_CLASS_MAPPINGS = {"SimpleAspectRatio": SimpleAspectRatio}
NODE_DISPLAY_NAME_MAPPINGS = {"SimpleAspectRatio": "Simple Aspect Ratio"}

"""TEST-only consumer: assert original scalar result and render that size."""
import torch
from comfy_api.latest import io


class MervynAspectRatioRenderOracle(io.ComfyNode):
    SDK_REFS = False
    SDK_PERMISSIONS = ()

    @classmethod
    def define_schema(cls):
        return io.Schema(
            node_id="MervynAspectRatioRenderOracle", category="tests/SimpleAspectRatio",
            inputs=[io.Int.Input("width"), io.Int.Input("height"),
                    io.Int.Input("expected_width"), io.Int.Input("expected_height")],
            outputs=[io.Image.Output()],
        )

    @classmethod
    def execute(cls, width, height, expected_width, expected_height):
        if type(width) is not int or type(height) is not int:
            raise AssertionError("SimpleAspectRatio TEST scalar output type differs")
        if (width, height) != (expected_width, expected_height):
            raise AssertionError("SimpleAspectRatio TEST dimensions differ from original")
        if not (1 <= width <= 2048 and 1 <= height <= 2048 and width * height <= 1048576):
            raise AssertionError("SimpleAspectRatio TEST oracle fixture exceeds its bound")
        image = torch.empty((1, height, width, 3), dtype=torch.float32, device="cpu")
        image[..., 0] = 0x12 / 255
        image[..., 1] = 0x34 / 255
        image[..., 2] = 0x56 / 255
        return io.NodeOutput(image)
